time ar_time[id_t][$];                     // per-ID queue: same-ID reads return in order

task automatic collect();
  forever begin
    @(vif.mon_cb);
    if (vif.mon_cb.arvalid && vif.mon_cb.arready)
      ar_time[vif.mon_cb.arid].push_back($time);
    if (vif.mon_cb.rvalid && vif.mon_cb.rready && vif.mon_cb.rlast) begin
      time t0 = ar_time[vif.mon_cb.rid].pop_front();
      lat_ap.write(lat_item::make(vif.mon_cb.rid, $time - t0));  // make(): a static helper in lat_item
    end
  end
endtask
